// Stage all VFX objects for a cinematic release. No scaling of the whole skill.
function prepareRelease(root,spellIndex){
 const mode=ritualModes[spellIndex];
 const objects=[];
 root.traverse(o=>{
  if(o===root||(!o.isMesh&&!o.isLine&&!o.isPoints))return;
  const origin=o.position.clone();
  const originalScale=o.scale.clone();
  const order=objects.length;
  const delay=(order%17)/17*.95;
  const theta=(order*2.39996);
  const distance=.8+(order%9)*.24;
  let offset=new THREE.Vector3(Math.cos(theta)*distance,0,Math.sin(theta)*distance);
  if(['collapse','gravity','void','rift'].includes(mode))offset.multiplyScalar(2.5);
  if(['ascend','eruption','geyser','pillars','cathedral','bloom'].includes(mode))offset.y=-2.8-(order%5)*.35;
  if(['fall','lantern','eclipse','flare'].includes(mode))offset.y=3+(order%5)*.5;
  if(['aurora','prism','shield'].includes(mode))offset.set((order%2?1:-1)*3.8,(order%4-2)*.65,Math.sin(theta)*2);
  if(['storm','cyclone','whirlpool','spiral','orbit'].includes(mode))offset.y=(order%6-3)*.6;
  const baseOpacity=o.material?.opacity;
  objects.push({o,origin,originalScale,offset,delay,theta,baseOpacity,order});
  o.visible=false;
 });
 return {objects,mode};
}
function animateRelease(release,a,dt,intensity){
 const {objects,mode}=release;
 objects.forEach(q=>{
  const {o,origin,originalScale,offset,delay,theta,baseOpacity,order}=q;
  const local=(a-delay*.68)/(.42+(order%5)*.12);
  if(local<=0){o.visible=false;return;}
  o.visible=true;
  const k=smooth(local),inv=1-k;
  o.position.copy(origin).addScaledVector(offset,inv);
  // At release, all elements emerge from the shared rune focus rather than popping in independently.
  const focus=new THREE.Vector3(0,2.65,0);
  const formation=smooth((a-delay*.68)/.32);
  if(formation<1)o.position.lerpVectors(focus,o.position,formation);
  // Different trajectories: swirls, falling stars, erupting crystals, shields, and fissures.
  if(['storm','cyclone','whirlpool','spiral','orbit','gravity','collapse'].includes(mode)){
   o.position.x+=Math.cos(theta+a*6)*inv*1.2;
   o.position.z+=Math.sin(theta+a*6)*inv*1.2;
  }
  if(['fall','flare','eruption','geyser','pillars','bloom','thorns'].includes(mode))o.position.y+=Math.sin(Math.PI*k)*(.4+order%3*.2);
  if(['shield','eclipse','sigil','cathedral'].includes(mode))o.rotation.y+=dt*(order%2?1:-1)*.65;
  if(['rift','prism','aurora'].includes(mode))o.rotation.z+=dt*(order%2?1:-1)*.8;
  // Meshes retain their actual size. Objects enter by movement and staggered visibility.
  o.scale.copy(originalScale);
  if(o.userData.grow){const g=smooth((a-delay*1.2)/.8);o.scale.y=originalScale.y*Math.max(.001,g);}
  if(baseOpacity!==undefined && !o.userData.shock)o.material.opacity=baseOpacity*(.15+.85*k);
 });
}
